package edu.pbs.hub.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notices") public class Notice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; @Column(length=3000) private String message; private String tag; private LocalDateTime createdAt=LocalDateTime.now(); private boolean active=true; public Notice(){} public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getTag(){return tag;} public void setTag(String v){tag=v;} public LocalDateTime getCreatedAt(){return createdAt;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
